#include "minishell.h"

char	*expand_string(t_shell *shell, char *str)
{
	if ((str[0] == '\'' && str[1] == '\'' && str[2] == '\0')
		|| (str[0] == '"' && str[1] == '"' && str[2] == '\0'))
		return (ft_strdup(""));
	if (is_simple_single_quote(str))
		return (ft_strdup(str + 1));
	return (expand_string_core(shell, str, ft_strdup("")));
}

char	*extract_var_name(t_shell *shell, char **ptr_i)
{
	int		start;
	char	*var_name;
	char	*value;

	start = 0;
	while (ft_isalnum((*ptr_i)[start]) || (*ptr_i)[start] == '_')
		start++;
	var_name = ft_substr(*ptr_i, 0, start);
	value = get_env_value(shell->env, var_name);
	free(var_name);
	*ptr_i += start;
	if (!value)
		return (ft_strdup(""));
	return (ft_strdup(value));
}

int	is_simple_single_quote(char *str)
{
	if (!str)
		return (0);
	if (str[0] != '\001')
		return (0);
	if (ft_strchr(str, '\002'))
		return (0);
	if (ft_strchr(str, '\003'))
		return (0);
	return (1);
}

#include "minishell.h"

void	expand_all(t_shell *shell)
{
	t_cmd	*cmd;

	cmd = shell->command_list;
	while (cmd)
	{
		expand_args(shell, cmd);
		expand_redirs(shell, cmd);
		cmd = cmd->next;
	}
}

char	*expand_string_core(t_shell *shell, char *str, char *result)
{
	char	*expanded_part;
	char	*str_ptr;
	int		in_single_quotes;

	str_ptr = str;
	in_single_quotes = 0;
	while (*str_ptr)
	{
		if (*str_ptr == '\001' || *str_ptr == '\002' || *str_ptr == '\003')
			handle_quote_chars(&str_ptr, &in_single_quotes);
		else
		{
			expanded_part = handle_regular_char(shell, str,
					&str_ptr, in_single_quotes);
			if (!expanded_part)
				return (free(result), NULL);
			result = join_and_free(result, expanded_part);
		}
	}
	return (result);
}

void	expand_args(t_shell *shell, t_cmd *cmd)
{
	int		i;
	char	*expanded;

	if (!cmd->argv)
		return ;
	i = -1;
	while (cmd->argv[++i])
	{
		if (i == 0 || !cmd->argv[0] || ft_strcmp(cmd->argv[0], "export") != 0)
		{
			expanded = expand_string(shell, cmd->argv[i]);
			free(cmd->argv[i]);
			cmd->argv[i] = expanded;
		}
		else
		{
			if (ft_strchr(cmd->argv[i], '='))
			{
				expanded = expand_string(shell, cmd->argv[i]);
				free(cmd->argv[i]);
				cmd->argv[i] = expanded;
			}
		}
	}
}

void	expand_redirs(t_shell *shell, t_cmd *cmd)
{
	t_redir	*redir;
	char	*expanded;

	redir = cmd->redir;
	while (redir)
	{
		expanded = expand_string(shell, redir->file);
		free(redir->file);
		redir->file = expanded;
		redir = redir->next;
	}
}

char	*expand_var(t_shell *shell, char *str, char **ptr_i)
{
	char	*result;

	(void)str;
	(*ptr_i)++;
	result = handle_special_vars(ptr_i);
	if (result)
		return (result);
	if (!ft_isalpha(**ptr_i) && **ptr_i != '_')
		return (ft_strdup("$"));
	return (extract_var_name(shell, ptr_i));
}

#include "minishell.h"

char	*handle_single_quotes(char **str_ptr)
{
	char	*result;
	char	*start;
	int		len;

	(*str_ptr)++;
	start = *str_ptr;
	len = 0;
	while (**str_ptr && **str_ptr != '\'')
	{
		len++;
		(*str_ptr)++;
	}
	if (**str_ptr == '\'')
		(*str_ptr)++;
	result = ft_substr(start, 0, len);
	return (result);
}

char	*handle_double_quotes(t_shell *shell, char **str_ptr)
{
	char	*result;
	char	*expanded_part;

	result = ft_strdup("");
	(*str_ptr)++;
	while (**str_ptr && **str_ptr != '"')
	{
		if (**str_ptr == '$')
			expanded_part = expand_var(shell, *str_ptr, str_ptr);
		else
		{
			expanded_part = ft_substr(*str_ptr, 0, 1);
			(*str_ptr)++;
		}
		if (!expanded_part)
			return (free(result), NULL);
		result = join_and_free(result, expanded_part);
	}
	if (**str_ptr == '"')
		(*str_ptr)++;
	return (result);
}

void	handle_quote_chars(char **str_ptr, int *in_single_quotes)
{
	if (**str_ptr == '\001')
	{
		*in_single_quotes = 1;
		(*str_ptr)++;
	}
	else if (**str_ptr == '\002')
	{
		*in_single_quotes = 0;
		(*str_ptr)++;
	}
	else if (**str_ptr == '\003')
	{
		*in_single_quotes = 0;
		(*str_ptr)++;
	}
}

char	*handle_regular_char(t_shell *shell, char *str, char **str_ptr,
			int in_single_quotes)
{
	char	*expanded_part;

	if (**str_ptr == '$' && !in_single_quotes)
		expanded_part = expand_var(shell, str, str_ptr);
	else
	{
		expanded_part = ft_substr(*str_ptr, 0, 1);
		(*str_ptr)++;
	}
	return (expanded_part);
}

char	*handle_special_vars(char **ptr_i)
{
	if (**ptr_i == '?')
	{
		(*ptr_i)++;
		return (ft_itoa(exit_status_manager(0, 0)));
	}
	if (**ptr_i == '$')
	{
		(*ptr_i)++;
		return (ft_strdup(""));
	}
	return (NULL);
}

#include "minishell.h"

