char	*extract_var_name(t_shell *shell, char **ptr_i)
{
	int		start;
	char	*var_name;
	char	*value;

	start = 0;
	while (ft_isalnum((*ptr_i)[start]) || (*ptr_i)[start] == '_')
		start++;
	var_name = ft_substr(*ptr_i, 0, start);
	value = get_env_value(shell->env, var_name);
